// Aggregate sc4sap subagent efficiency from Claude Code transcripts.
// Usage: node measure-agents.mjs <projectsDir> <sinceISO> <outJson>
import fs from 'node:fs';
import path from 'node:path';

const [root, since = '2026-09-01', out] = process.argv.slice(2);
const PRICE = { opus: [5, 25], sonnet: [3, 15], haiku: [1, 5], fable: [5, 25] }; // $/M in, out (relative is what matters)
const tier = (m = '') => (/haiku/i.test(m) ? 'haiku' : /sonnet/i.test(m) ? 'sonnet' : /fable/i.test(m) ? 'fable' : 'opus');

function walk(dir, acc) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, acc);
    else if (e.name.endsWith('.meta.json') && dir.endsWith('subagents')) acc.push(p);
  }
  return acc;
}

// Map a dispatch to a skill dispatch point by agent type + description.
function point(type, desc) {
  const d = desc || '';
  if (/bucket B\d/i.test(d)) return 'create-program P6 버킷 리뷰';
  if (type.endsWith('sap-code-reviewer') && /MAJOR|escalat|opus/i.test(d)) return 'create-program P6 Opus 재리뷰';
  if (type.endsWith('sap-checker')) {
    if (/^Facts/i.test(d)) return 'compare-programs 사실 추출';
    if (/verify|screen|gui|text ?pool|inactive|count/i.test(d)) return 'create-program P4 검증 checker';
    if (/scout|ddic|brief/i.test(d)) return 'create-program DDIC 스카우트';
    if (/detect|D\d/i.test(d)) return 'analyze-code/P6 detector';
    if (/evidence|check/i.test(d)) return 'analyze-code 증거 확인';
    return 'checker (기타)';
  }
  if (type.endsWith('sap-writer')) {
    if (/synth/i.test(d)) return 'ask-consultant 종합(writer)';
    if (/spec/i.test(d)) return 'create-program P3 스펙(writer)';
    if (/report/i.test(d)) return 'create-program P8 리포트(writer)';
    if (/translat|english|companion/i.test(d)) return 'writer 번역/영문본';
    return 'writer (기타)';
  }
  if (type.endsWith('sap-executor')) {
    if (/Create \+ implement|ECC DDIC helper/i.test(d)) return 'create-object executor';
    if (/fix/i.test(d)) return 'executor 수정 적용';
    return 'create-program P4 executor';
  }
  if (type.endsWith('sap-debugger')) return /Symptom triage/i.test(d) ? 'analyze-symptom 디버거' : 'debugger (기타)';
  if (type.endsWith('sap-code-reviewer')) return 'analyze-code 리뷰어';
  if (type.endsWith('sap-critic')) return /terms?\b/i.test(d) ? 'config-doc 용어 리뷰(critic)' : 'critic 리뷰';
  if (/consultant$/.test(type)) {
    if (/blocked/i.test(d)) return 'assist 차단 원인(consultant)';
    if (/consultation/i.test(d)) return 'ask-consultant 컨설턴트';
    if (/notes|batch|b\d{3}|terms|fields|values|badi|f\d{3}|v\d{3}|t\d{3}/i.test(d)) return 'config-doc 노트 작성(consultant)';
    return 'consultant (기타)';
  }
  if (type.endsWith('sap-stocker')) return 'stocker';
  if (type.endsWith('sap-analyst')) return 'analyst';
  if (type.endsWith('sap-planner')) return 'planner';
  if (type.endsWith('sap-qa-tester')) return 'qa-tester';
  return type.replace('sc4sap:', '') + ' (기타)';
}

const metas = walk(root, []);
const groups = {};
let n = 0;
for (const mp of metas) {
  let meta;
  try { meta = JSON.parse(fs.readFileSync(mp, 'utf8')); } catch { continue; }
  if (!String(meta.agentType || '').startsWith('sc4sap:')) continue;
  const jp = mp.replace(/\.meta\.json$/, '.jsonl');
  if (!fs.existsSync(jp)) continue;
  const lines = fs.readFileSync(jp, 'utf8').split('\n').filter(Boolean);
  let first; try { first = JSON.parse(lines[0]); } catch { continue; }
  if ((first.timestamp || '') < since) continue;

  const seen = new Map(); // message.id -> {usage, model}
  let tools = 0, outChars = 0, lastText = '';
  for (const l of lines) {
    let o; try { o = JSON.parse(l); } catch { continue; }
    if (o.type !== 'assistant' || !o.message) continue;
    const m = o.message;
    if (m.id && m.usage && !seen.has(m.id)) seen.set(m.id, { u: m.usage, model: m.model });
    for (const c of m.content || []) {
      if (c.type === 'tool_use') { tools++; outChars += JSON.stringify(c.input || {}).length; }
      else if (c.type === 'text') { outChars += c.text.length; lastText = c.text; }
      else if (c.type === 'thinking') outChars += (c.thinking || '').length;
    }
  }
  if (!seen.size) continue;
  const calls = [...seen.values()];
  const ctx = (u) => (u.input_tokens || 0) + (u.cache_creation_input_tokens || 0) + (u.cache_read_input_tokens || 0);
  const base = ctx(calls[0].u);
  const totalIn = calls.reduce((s, c) => s + ctx(c.u), 0);
  const t = tier(calls[0].model || meta.model);
  const [pi, po] = PRICE[t];
  const cost = calls.reduce((s, c) => s + ((c.u.input_tokens || 0) + 1.25 * (c.u.cache_creation_input_tokens || 0) + 0.1 * (c.u.cache_read_input_tokens || 0)) * pi / 1e6, 0)
    + (outChars / 3) * po / 1e6;
  // fixed spawn tax: the first call's full context, paid as cache write
  const tax = base * 1.25 * pi / 1e6;

  const key = point(meta.agentType, meta.description);
  const g = (groups[key] ||= { spawns: 0, calls: 0, tools: 0, totalIn: 0, base: 0, cost: 0, tax: 0, retChars: 0, oneShot: 0, models: {}, samples: new Set() });
  g.spawns++; g.calls += calls.length; g.tools += tools; g.totalIn += totalIn; g.base += base;
  g.cost += cost; g.tax += tax; g.retChars += lastText.length;
  if (tools <= 2) g.oneShot++;
  g.models[t] = (g.models[t] || 0) + 1;
  if (g.samples.size < 3) g.samples.add(meta.description);
  n++;
}

const rows = Object.entries(groups).map(([k, g]) => {
  const toolsPer = g.tools / g.spawns;
  const taxShare = g.tax / g.cost;                      // share of spend that is pure spawn overhead
  const density = Math.min(toolsPer / 8, 1);            // ≥8 tool calls per spawn = full marks
  const notTrivial = 1 - g.oneShot / g.spawns;          // spawns doing ≤2 tool calls are "do it yourself" work
  const score = Math.round(100 * (0.4 * (1 - taxShare) + 0.35 * density + 0.25 * notTrivial));
  return {
    point: k, spawns: g.spawns, models: g.models,
    toolsPerSpawn: +toolsPer.toFixed(1), callsPerSpawn: +(g.calls / g.spawns).toFixed(1),
    baseCtxK: Math.round(g.base / g.spawns / 1000), inPerSpawnK: Math.round(g.totalIn / g.spawns / 1000),
    taxShare: +(taxShare * 100).toFixed(0), trivialPct: Math.round(100 * g.oneShot / g.spawns),
    costPerSpawn: +(g.cost / g.spawns).toFixed(3), costTotal: +g.cost.toFixed(2), taxTotal: +g.tax.toFixed(2),
    retCharsAvg: Math.round(g.retChars / g.spawns), score, samples: [...g.samples],
  };
}).sort((a, b) => a.score - b.score);

fs.writeFileSync(out, JSON.stringify({ since, agents: n, rows }, null, 2));
console.log(`agents=${n}`);
for (const r of rows) console.log([r.score, r.point, `n=${r.spawns}`, `tools/spawn=${r.toolsPerSpawn}`, `calls=${r.callsPerSpawn}`, `base=${r.baseCtxK}k`, `tax=${r.taxShare}%`, `trivial=${r.trivialPct}%`, `$/spawn=${r.costPerSpawn}`, `$tot=${r.costTotal}`, JSON.stringify(r.models)].join(' | '));

