// config-to-document: review yield (corrections) vs agent cost, per module × kind × role.
// Usage: node measure-configdoc.mjs <projectsDir> <configDocsDir> <outJson>
import fs from 'node:fs';
import path from 'node:path';

const [projRoot, docsRoot, out] = process.argv.slice(2);
const PRICE = { opus: [5, 25], sonnet: [3, 15], haiku: [1, 5] };
const tier = (m = '') => (/haiku/i.test(m) ? 'haiku' : /sonnet/i.test(m) ? 'sonnet' : 'opus');
const KIND = { b: 'notes', f: 'fields', v: 'values', t: 'terms' };

// ---------- 1. review yield from saved files ----------
const yieldRows = {}; // key module|kind
const issueCats = {};
const catOf = (s) => {
  if (/source|출처|url|sapdatasheet|help\.sap|note|kba|링크|공식/i.test(s)) return 'source/URL';
  if (/count|건수|개수|행|rows?\b|\d+\s*(건|개)/i.test(s)) return 'count/data';
  if (/ecc|s\/4|s4/i.test(s)) return 'ECC vs S/4';
  if (/tcode|transaction|트랜잭션|t-?code/i.test(s)) return 'TCode';
  return 'meaning/other';
};
for (const mod of fs.readdirSync(docsRoot)) {
  for (const kind of ['notes', 'fields', 'values', 'terms']) {
    const dir = path.join(docsRoot, mod, kind);
    if (!fs.existsSync(dir)) continue;
    for (const f of fs.readdirSync(dir).filter((x) => x.endsWith('.review.json'))) {
      const batch = f.split('.')[0];
      const rev = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')).items || {};
      const draftP = path.join(dir, `${batch}.draft.json`);
      const draft = fs.existsSync(draftP) ? JSON.parse(fs.readFileSync(draftP, 'utf8')).items || {} : {};
      const unitsIn = (o) => (kind === 'values' ? Object.values(o).reduce((s, v) => s + (v && typeof v === 'object' ? Object.keys(v).length : 1), 0) : Object.keys(o).length);
      let checked = unitsIn(draft), fixed;
      if (kind === 'notes') {
        const vals = Object.values(rev);
        checked = vals.length || checked;
        const fx = vals.filter((v) => v && v.verdict === 'fix');
        fixed = fx.length;
        for (const v of fx) for (const s of v.issues || []) { const c = catOf(s); issueCats[c] = (issueCats[c] || 0) + 1; }
      } else fixed = unitsIn(rev);
      const k = `${mod}|${kind}`;
      const y = (yieldRows[k] ||= { batches: 0, checked: 0, fixed: 0 });
      y.batches++; y.checked += checked; y.fixed += fixed;
    }
  }
}

// ---------- 2. agent cost per module × kind × role ----------
function walk(d, acc) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p, acc);
    else if (e.name.endsWith('.meta.json') && d.endsWith('subagents')) acc.push(p);
  }
  return acc;
}
const cost = {};
for (const mp of walk(projRoot, [])) {
  let m; try { m = JSON.parse(fs.readFileSync(mp, 'utf8')); } catch { continue; }
  const t = m.agentType || '', d = m.description || '';
  if (!/sap-critic|consultant/.test(t)) continue;
  const mod = (d.match(/\b(FI|CO|PP|LE|MM|SD|STO)\b/) || [])[1];
  if (!mod) continue;
  let kind = /field/i.test(d) ? 'fields' : /value/i.test(d) ? 'values' : /term/i.test(d) ? 'terms' : /badi/i.test(d) ? 'badi' : /note|revis|b\d{3}/i.test(d) ? 'notes' : null;
  if (!kind) continue;
  const role = /critic/.test(t) ? 'review' : /revis/i.test(d) ? 'revision' : 'writer';
  const jp = mp.replace(/\.meta\.json$/, '.jsonl');
  if (!fs.existsSync(jp)) continue;
  const seen = new Map(); let outChars = 0, model = m.model;
  for (const l of fs.readFileSync(jp, 'utf8').split('\n')) {
    if (!l) continue; let o; try { o = JSON.parse(l); } catch { continue; }
    if (o.type !== 'assistant' || !o.message) continue;
    const msg = o.message; model = msg.model || model;
    if (msg.id && msg.usage && !seen.has(msg.id)) seen.set(msg.id, msg.usage);
    for (const c of msg.content || []) outChars += c.type === 'tool_use' ? JSON.stringify(c.input || {}).length : (c.text || c.thinking || '').length;
  }
  const [pi, po] = PRICE[tier(model)];
  const usd = [...seen.values()].reduce((s, u) => s + ((u.input_tokens || 0) + 1.25 * (u.cache_creation_input_tokens || 0) + 0.1 * (u.cache_read_input_tokens || 0)) * pi / 1e6, 0) + (outChars / 3) * po / 1e6;
  const k = `${mod}|${kind}|${role}`;
  const c = (cost[k] ||= { n: 0, usd: 0, models: {} });
  c.n++; c.usd += usd; c.models[tier(model)] = (c.models[tier(model)] || 0) + 1;
}

// ---------- 3. report ----------
const byKind = {};
for (const [k, c] of Object.entries(cost)) {
  const [, kind, role] = k.split('|');
  const r = ((byKind[kind] ||= {})[role] ||= { n: 0, usd: 0, models: {} });
  r.n += c.n; r.usd += c.usd; for (const [mm, v] of Object.entries(c.models)) r.models[mm] = (r.models[mm] || 0) + v;
}
const yk = {};
for (const [k, y] of Object.entries(yieldRows)) {
  const kind = k.split('|')[1]; const r = (yk[kind] ||= { batches: 0, checked: 0, fixed: 0 });
  r.batches += y.batches; r.checked += y.checked; r.fixed += y.fixed;
}
console.log('KIND | role | runs | $ | models');
for (const [kind, roles] of Object.entries(byKind)) for (const [role, r] of Object.entries(roles)) console.log([kind, role, r.n, r.usd.toFixed(0), JSON.stringify(r.models)].join(' | '));
console.log('\nYIELD kind | batches | checked units | fixed | fix% | review $ per fix');
for (const [kind, y] of Object.entries(yk)) {
  const rv = byKind[kind]?.review?.usd || 0;
  console.log([kind, y.batches, y.checked, y.fixed, (100 * y.fixed / Math.max(y.checked, 1)).toFixed(1) + '%', y.fixed ? '$' + (rv / y.fixed).toFixed(2) : '-'].join(' | '));
}
console.log('\nYIELD per module (notes only): module | checked | fixed | fix%');
for (const [k, y] of Object.entries(yieldRows)) if (k.endsWith('|notes')) console.log(k.split('|')[0], '|', y.checked, '|', y.fixed, '|', (100 * y.fixed / Math.max(y.checked, 1)).toFixed(0) + '%');
console.log('\nNOTES issue categories:', JSON.stringify(issueCats));
fs.writeFileSync(out, JSON.stringify({ byKind, yieldRows, yk, issueCats, cost }, null, 2));

