1	#!/usr/bin/env node
2	// config-to-document — consultant notes (written by the module consultant agent,
3	// reviewed by a second agent) for the IMG activities of a snapshot.
4	//
5	//   node scripts/config/notes.mjs scopes --module MM [--size 12]
6	//        → activities and batches per scope (custom | values | all), reviewed ones left out
7	//   node scripts/config/notes.mjs batches --module MM [--scope custom|values|all] [--size 12] [--redo]
8	//        → notes/_in/bNNN.json per batch (activity context for the writer) + manifest on stdout
9	//   node scripts/config/notes.mjs batches --module FI --ids SIMG_CFMENUORFBOB28,SIMG_CFMENUORFBOBBH
10	//        → one new batch of exactly these activities, reviewed or not (after new data for them)
11	//   node scripts/config/notes.mjs save --module MM --batch b001 --kind draft|review|revised  < text
12	//        → notes/b001.<kind>.json (text in the marker format below, parsed and validated)
13	//   node scripts/config/notes.mjs terms --module MM
14	//        → terms/_in/tNNN.json: names without a document-language text (150 per batch);
15	//          save with --batch tNNN --kind draft|review, lines `tNNN-NNN = <translation>`
16	//   node scripts/config/notes.mjs status --module MM
17	//   node scripts/config/notes.mjs sources --module MM
18	//        → seeds the verified-source cache (notes-sources.mjs) from every reviewed batch
19	//
20	// Marker format (draft / revised):        Marker format (review):
21	//   @@ <IMG activity id>                    @@ <IMG activity id>
22	//   ## purpose                              verdict: ok | fix
23	//   <one or two sentences>                  - <what is wrong, what the data says>
24	//   ## impact
25	//   - <bullet>            (also: ## cautions, ## refs)
26	
27	import { readFileSync, existsSync, readdirSync } from 'fs';
28	import { join, resolve, dirname } from 'path';
29	import { fileURLToPath } from 'url';
30	import { resolveArtifactBase, sc4sapHome } from '../lib/profile-resolve.mjs';
31	import { atomicWriteFileSync, ensureDirSync } from '../lib/atomic-write.mjs';
32	import { buildModel } from './build-config-doc.mjs';
33	import { loadRules, runChecks, attachActivities } from './config-checks.mjs';
34	import { readSources, recordSources, sourceHints } from './notes-sources.mjs';
35	
36	const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
37	const CONTEXT_ROWS = 15;
38	
39	function opts(argv) {
40	  const o = { cmd: argv[0], module: '', scope: 'custom', size: 12, batch: '', kind: '', redo: false, file: '', ids: [] };
41	  for (let i = 1; i < argv.length; i++) {
42	    const a = argv[i];
43	    if (a === '--module') o.module = String(argv[++i]).toUpperCase();
44	    else if (a === '--scope') o.scope = argv[++i];
45	    else if (a === '--size') o.size = Math.max(1, Number(argv[++i]) || 12);
46	    else if (a === '--batch') o.batch = argv[++i];
47	    else if (a === '--kind') o.kind = argv[++i];
48	    else if (a === '--redo') o.redo = true;
49	    else if (a === '--file') o.file = argv[++i];
50	    else if (a === '--ids') o.ids = String(argv[++i]).split(',').map((x) => x.trim()).filter(Boolean);
51	  }
52	  if (!o.module) throw new Error('--module is required');
53	  return o;
54	}
55	
56	const dirOf = (module) => join(resolveArtifactBase(process.cwd()), 'config-docs', module);
57	
58	// Sources of the reference panel: official SAP documentation only — SAP Help
59	// Portal, SAP Notes / KBAs, SAP Learning. Anything else is refused on save and
60	// dropped by the builder.
61	const OFFICIAL_HOSTS = ['help.sap.com', 'me.sap.com', 'launchpad.support.sap.com', 'userapps.support.sap.com', 'support.sap.com', 'learning.sap.com'];
62	export function isOfficialSource(url) {
63	  try {
64	    const u = new URL(String(url));
65	    return u.protocol === 'https:' && OFFICIAL_HOSTS.includes(u.hostname.toLowerCase());
66	  } catch {
67	    return false;
68	  }
69	}
70	
71	const bullet = (l) => l.replace(/^\s*[-*]\s+/, '').trim();
72	const kv = (l) => /^\s*([a-z0-9]+)\s*:\s*(.*)$/i.exec(l);
73	
74	/** One activity's note: the notes card (purpose … refs) and the reference panel (sapdoc … sources). */
75	function parseNote(body) {
76	  const note = { purpose: '', impact: [], cautions: [], refs: [], sapdoc: '', cases: null, mix: '', compare: [], checklist: [], criteria: {}, sources: [], verdicts: [] };
77	  let sec = null;
78	  let kase = null;
79	  for (const raw of body.split('\n')) {
80	    const line = raw.trimEnd();
81	    const sub = /^###\s*case\b\s*(.*)$/i.exec(line);
82	    if (sub && sec === 'cases') { kase = { title: sub[1].trim(), flow: [], desc: '', when: '', thisSystem: '' }; note.cases.list.push(kase); continue; }
83	    const h = /^##\s*(\w+)\s*(.*)$/.exec(line);
84	    if (h) {
85	      sec = h[1].toLowerCase();
86	      kase = null;
87	      if (sec === 'cases') note.cases = { title: h[2].trim(), list: [] };
88	      continue;
89	    }
90	    if (!sec || !line.trim()) continue;
91	    if (sec === 'purpose' || sec === 'sapdoc' || sec === 'mix') note[sec] = `${note[sec]} ${line.trim()}`.trim();
92	    else if (['impact', 'cautions', 'refs', 'checklist'].includes(sec)) note[sec].push(bullet(line));
93	    else if (sec === 'cases' && kase) {
94	      const m = kv(line);
95	      if (m && m[1].toLowerCase() === 'flow') kase.flow = m[2].split('>').map((s) => s.trim()).filter(Boolean);
96	      else if (m && ['desc', 'when'].includes(m[1].toLowerCase())) kase[m[1].toLowerCase()] = m[2].trim();
97	      else if (m && m[1].toLowerCase() === 'this') kase.thisSystem = m[2].trim();
98	      else kase.desc = `${kase.desc} ${line.trim()}`.trim();
99	    } else if (sec === 'compare' && line.includes('|')) {
100	      const cells = line.replace(/^\s*\|/, '').replace(/\|\s*$/, '').split('|').map((s) => s.trim());
101	      if (!cells.every((c) => /^:?-{2,}:?$/.test(c))) note.compare.push(cells);
102	    } else if (sec === 'criteria') {
103	      const m = kv(line);
104	      if (m) note.criteria[m[1].toLowerCase()] = m[2].trim();
105	    } else if (sec === 'verdicts') {
106	      // System-only notes (general part from the knowledge base): `CASE 2: yes — <evidence>`.
107	      const m = /^\s*-?\s*CASE\s*(\d+)\s*:\s*(.+)$/i.exec(line);
108	      if (m) note.verdicts.push({ n: Number(m[1]), value: m[2].trim() });
109	    } else if (sec === 'sources') {
110	      const [title = '', source = '', url = '', summary = ''] = bullet(line).split('|').map((s) => s.trim());
111	      if (title) note.sources.push({ title, source, url, summary });
112	    }
113	  }
114	  return note;
115	}
116	
117	/** Parse the marker text; returns { items: {id: {...}}, errors: [] }. */
118	export function parseNotes(text, kind) {
119	  const items = {};
120	  const errors = [];
121	  for (const chunk of String(text).replace(/\r\n/g, '\n').split(/^@@\s*/m).slice(1)) {
122	    const [head, ...rest] = chunk.split('\n');
123	    const id = head.trim();
124	    if (!id) continue;
125	    const body = rest.join('\n');
126	    if (kind === 'review') {
127	      const verdict = /^verdict:\s*(ok|fix)\b/im.exec(body)?.[1]?.toLowerCase();
128	      if (!verdict) errors.push(`${id}: no "verdict: ok|fix" line`);
129	      items[id] = { verdict: verdict || 'fix', issues: body.split('\n').filter((l) => /^\s*-\s+/.test(l)).map((l) => l.replace(/^\s*-\s+/, '').trim()) };
130	      continue;
131	    }
132	    items[id] = parseNote(body);
133	    if (!items[id].purpose) errors.push(`${id}: empty purpose`);
134	    for (const s of items[id].sources.filter((x) => !isOfficialSource(x.url))) errors.push(`${id}: source not official SAP documentation (${s.url || s.title}) — use help.sap.com, SAP Notes/KBAs or learning.sap.com`);
135	  }
136	  return { items, errors };
137	}
138	
139	// Sample rows for the writer: customer rows first, codes with their fixed-value text.
140	function rowsFor(v, domains) {
141	  const order = [...v.cust, ...v.rows.map((_, i) => i).filter((i) => !v.cust.includes(i))].slice(0, CONTEXT_ROWS);
142	  // Two columns may share a label (plant / plant name): name them by field then.
143	  const seen = v.cols.reduce((m, c) => m.set(c.label, (m.get(c.label) || 0) + 1), new Map());
144	  const names = v.cols.map((c) => (seen.get(c.label) > 1 ? `${c.label} [${c.name}]` : c.label));
145	  return order.map((i) => Object.fromEntries(v.cols.map((c, j) => {
146	    const x = v.rows[i][j];
147	    const tx = c.dom && domains[c.dom]?.[x];
148	    return [names[j], tx ? `${x} (${tx})` : x];
149	  }).filter(([, x]) => x !== '')));
150	}
151	
152	function batches(o) {
153	  const dir = dirOf(o.module);
154	  const snap = JSON.parse(readFileSync(join(dir, 'snapshot.json'), 'utf8'));
155	  const lang = snap.meta.lang || 'ko';
156	  snap.__theme = undefined;
157	  const { views, acts } = buildModel(snap, lang, { drawScreens: false });
158	  const rules = loadRules(join(ROOT, 'configs', o.module, 'config-checks.json'));
159	  const checks = attachActivities(runChecks(snap, rules, (a) => (acts[a.id] ? acts[a.id].viewKeys.map((k) => ({ tables: [views[k].root] })) : []), lang), rules, acts)
160	    .filter((c) => c.items.length);
161	  const paths = {};
162	  const order = [];
163	  const walk = (nodes, path) => nodes.forEach((n) => (n.kind === 'activity' ? (paths[n.activity] = path, order.push(n.activity)) : walk(n.children || [], n.text ? [...path, n.text] : path)));
164	  walk(snap.tree, []);
165	  const SCOPES = { custom: ['custom'], values: ['custom', 'standard', 'empty'], all: null };
166	  // Activities that already have reviewed notes are skipped unless --redo.
167	  const done = new Set(Object.entries(loadNotes(dir)).filter(([, n]) => !o.redo && ['ok', 'revised'].includes(n.review)).map(([id]) => id));
168	  const pick = (scope) => [...new Set(order)].filter((id) => acts[id] && !done.has(id) && (!SCOPES[scope] || SCOPES[scope].includes(acts[id].status)));
169	  if (o.cmd === 'scopes') {
170	    const out = Object.fromEntries(Object.keys(SCOPES).map((s) => [s, { activities: pick(s).length, batches: Math.ceil(pick(s).length / o.size) }]));
171	    process.stdout.write(JSON.stringify({ size: o.size, alreadyReviewed: done.size, ...out }, null, 1) + '\n');
172	    return;
173	  }
174	  if (!(o.scope in SCOPES)) throw new Error('--scope custom | values | all');
175	  // Activities already in a batch input (written, under review or waiting) are not batched again.
176	  const batched = new Set(existsSync(join(dir, 'notes', '_in')) ? readdirSync(join(dir, 'notes', '_in')).filter((f) => /^b\d{3}\.json$/.test(f))
177	    .flatMap((f) => JSON.parse(readFileSync(join(dir, 'notes', '_in', f), 'utf8')).items.map((x) => x.id)) : []);
178	  const unknown = o.ids.filter((id) => !acts[id]);
179	  if (unknown.length) throw new Error(`unknown activities: ${unknown.join(', ')}`);
180	  const ids = o.ids.length ? [...new Set(o.ids)] : pick(o.scope).filter((id) => o.redo || !batched.has(id));
181	  // 1000 characters cut 40% of the IMG docs (PP: Heijunka missing from the TSPP0 doc); 6000 covers 99%.
182	  const docText = (id) => {
183	    const t = (snap.docs[acts[id].docuId]?.blocks || []).map((b) => b.text).join(' ');
184	    return t.length > 6000 ? `${t.slice(0, 6000)} … (cut; full text in snapshot.docs)` : t;
185	  };
186	  // Activities whose general part (purpose, SAP documentation, cases, criteria,
187	  // sources) is already in the knowledge base get only the system part written.
188	  const kb = (id) => kbRead(o.module, lang, id);
189	  // Full items carry the sources earlier reviews accepted for the same activity or tables.
190	  const cache = readSources(o.module, lang);
191	  const inDir = join(dir, 'notes', '_in');
192	  ensureDirSync(inDir);
193	  const manifest = [];
194	  // New batches are numbered after every existing batch input, so no batch — written,
195	  // in progress or waiting — is ever overwritten.
196	  const first = Math.max(0, ...readdirSync(inDir).map((f) => Number(/^b(\d{3})\.json$/.exec(f)?.[1] || 0)));
197	  for (let i = 0; i < ids.length; i += o.size) {
198	    const name = `b${String(first + i / o.size + 1).padStart(3, '0')}`;
199	    const items = ids.slice(i, i + o.size).map((id) => {
200	      const a = acts[id];
201	      const known = kb(id) ? [] : sourceHints(cache, id, a.viewKeys.map((k) => views[k].root));
202	      return {
203	        id, path: paths[id], title: a.title, titleEn: a.titleEn, tcode: a.tcode, status: a.status,
204	        // Counts of a truncated read are partial; a view whose condition is not applied, or whose
205	        // subset field SM30 asks for, shows rows of every value (all countries, all applications).
206	        objects: a.viewKeys.map((k) => ({ key: k, title: views[k].title, table: views[k].root, rows: views[k].rows.length, customerRows: views[k].cust.length,
207	          ...(views[k].truncated ? { truncated: true } : {}), ...(views[k].conditionNotApplied ? { conditionNotApplied: views[k].conditionNotApplied } : {}), ...(views[k].subset ? { subset: views[k].subset } : {}),
208	          columns: views[k].cols.map((c) => `${c.label} [${c.name}]`), sample: rowsFor(views[k], snap.domains || {}) })),
209	        checks: checks.filter((c) => c.activities.includes(id)).map((c) => ({ severity: c.severity, title: c.title, items: c.items.slice(0, 10) })),
210	        ...(kb(id)
211	          ? { mode: 'system', kb: { purpose: kb(id).purpose, cases: (kb(id).cases?.list || []).map((c, n) => `CASE ${n + 1}: ${c.title} — ${c.desc}`) } }
212	          : { mode: 'full', sapDoc: docText(id), ...(known.length ? { knownSources: known } : {}) }),
213	      };
214	    });
215	    atomicWriteFileSync(join(inDir, `${name}.json`), JSON.stringify({ module: o.module, system: snap.meta.system, lang, items }, null, 1));
216	    manifest.push({ batch: name, file: join(inDir, `${name}.json`), activities: items.length });
217	  }
218	  process.stdout.write(JSON.stringify({ scope: o.scope, activities: ids.length, batches: manifest }, null, 1) + '\n');
219	}
220	
221	function saveTerms(o) {
222	  if (!['draft', 'review'].includes(o.kind)) throw new Error('term batches take --kind draft|review');
223	  const dir = join(dirOf(o.module), 'terms');
224	  const input = JSON.parse(readFileSync(join(dir, '_in', `${o.batch}.json`), 'utf8'));
225	  const known = new Set(input.items.map((x) => x.id));
226	  const items = parseTerms(readFileSync(o.file || 0, 'utf8'));
227	  const errors = Object.keys(items).filter((id) => !known.has(id)).map((id) => `${id}: not in batch ${o.batch}`);
228	  for (const id of Object.keys(items)) if (!known.has(id)) delete items[id];
229	  if (o.kind === 'draft') for (const id of known) if (!items[id]) errors.push(`${id}: missing`);
230	  atomicWriteFileSync(join(dir, `${o.batch}.${o.kind}.json`), JSON.stringify({ batch: o.batch, kind: o.kind, savedAt: new Date().toISOString(), items }, null, 1));
231	  process.stdout.write(JSON.stringify({ ok: errors.length === 0, saved: Object.keys(items).length, errors }) + '\n');
232	}
233	
234	function save(o) {
235	  if (/^t\d{3}$/.test(o.batch)) return saveTerms(o);
236	  if (!/^b\d{3}$/.test(o.batch) || !['draft', 'review', 'revised'].includes(o.kind)) throw new Error('--batch bNNN and --kind draft|review|revised are required');
237	  const dir = join(dirOf(o.module), 'notes');
238	  const input = JSON.parse(readFileSync(join(dir, '_in', `${o.batch}.json`), 'utf8'));
239	  const known = new Set(input.items.map((x) => x.id));
240	  const parsed = parseNotes(readFileSync(o.file || 0, 'utf8'), o.kind);
241	  const { items } = parsed;
242	  // System-only items (general part in the knowledge base) need no purpose, but a verdict per KB case.
243	  const systemOnly = new Map(input.items.filter((x) => x.mode === 'system').map((x) => [x.id, x.kb.cases.length]));
244	  const errors = parsed.errors.filter((e) => !(systemOnly.has(e.split(':')[0]) && /empty purpose/.test(e)));
245	  if (o.kind !== 'review') {
246	    for (const [id, n] of systemOnly) if (items[id] && items[id].verdicts.length < n && !items[id].cases) errors.push(`${id}: needs a "## verdicts" line for each of its ${n} cases`);
247	  }
248	  for (const id of Object.keys(items)) if (!known.has(id)) { errors.push(`${id}: not in batch ${o.batch}`); delete items[id]; }
249	  if (o.kind !== 'revised') for (const id of known) if (!items[id]) errors.push(`${id}: missing`);
250	  // Revisions accumulate: a later follow-up revision replaces only the items it carries.
251	  const out = join(dir, `${o.batch}.${o.kind}.json`);
252	  const kept = o.kind === 'revised' && existsSync(out) ? JSON.parse(readFileSync(out, 'utf8')).items : {};
253	  atomicWriteFileSync(out, JSON.stringify({ batch: o.batch, kind: o.kind, savedAt: new Date().toISOString(), items: { ...kept, ...items } }, null, 1));
254	  const fix = o.kind === 'review' ? Object.entries(items).filter(([, r]) => r.verdict === 'fix').map(([id]) => id) : [];
255	  // Sources of the notes the reviewer passed are verified for later batches.
256	  if (o.kind === 'review') acceptSources(o.module, input, dir, o.batch, new Set(Object.keys(items).filter((id) => items[id].verdict === 'ok')));
257	  process.stdout.write(JSON.stringify({ ok: errors.length === 0, saved: Object.keys(items).length, errors, ...(o.kind === 'review' ? { fix } : {}) }) + '\n');
258	}
259	
260	function acceptSources(module, input, dir, batch, okIds) {
261	  const f = join(dir, `${batch}.draft.json`);
262	  if (!okIds.size || !existsSync(f)) return { added: 0 };
263	  const draft = JSON.parse(readFileSync(f, 'utf8')).items;
264	  const entries = input.items.filter((x) => okIds.has(x.id) && draft[x.id])
265	    .map((x) => ({ id: x.id, tables: x.objects.map((ob) => ob.table), sources: (draft[x.id].sources || []).filter((s) => isOfficialSource(s.url)) }));
266	  return recordSources(module, input.lang || 'ko', entries, `${batch} review`);
267	}
268	
269	/** Seed the source cache from every batch already reviewed. */
270	function seedSources(o) {
271	  const dir = join(dirOf(o.module), 'notes');
272	  let added = 0, urls = 0;
273	  for (const b of readdirSync(join(dir, '_in')).filter((f) => /^b\d{3}\.json$/.test(f)).map((f) => f.slice(0, 4))) {
274	    if (!existsSync(join(dir, `${b}.review.json`))) continue;
275	    const review = JSON.parse(readFileSync(join(dir, `${b}.review.json`), 'utf8')).items;
276	    const input = JSON.parse(readFileSync(join(dir, '_in', `${b}.json`), 'utf8'));
277	    const r = acceptSources(o.module, input, dir, b, new Set(Object.keys(review).filter((id) => review[id].verdict === 'ok')));
278	    added += r.added || 0;
279	    urls = r.urls || urls;
280	  }
281	  process.stdout.write(JSON.stringify({ added, urls }) + '\n');
282	}
283	
284	// ── terms: names SAP has no document-language text for (IMG folders, activity
285	// titles, field labels), translated by the consultant agent and corrected by the
286	// reviewer. Marker format: one line per term, `t0001 = <translation>`; the review
287	// lists corrections only: `t0001 = <corrected> | <reason>`.
288	const hasKo = (t) => /[가-힣]/.test(String(t || ''));
289	
290	function termSources(snap) {
291	  const out = [];
292	  // Labels carry their data element and long text, so an abbreviation is not guessed.
293	  const add = (kind, en, ctx = {}) => { if (en && !hasKo(en) && /[A-Za-z]/.test(en)) out.push({ kind, en, ...ctx }); };
294	  const walk = (nodes) => nodes.forEach((n) => (n.kind === 'folder' ? (add('folder', n.text || n.textEn), walk(n.children || [])) : null));
295	  walk(snap.tree);
296	  for (const a of Object.values(snap.activities)) add('activity', a.title || a.titleEn);
297	  const used = new Set(Object.values(snap.tables).flatMap((t) => (t.fields || []).map((f) => f.rollname)));
298	  for (const [r, l] of Object.entries(snap.labels)) if (used.has(r)) add('label', l.m || l.s || l.l || l.h || l.d, { dataElement: r, longText: l.d || l.l || '' });
299	  const seen = new Set();
300	  return out.filter((x) => !seen.has(`${x.kind}|${x.en}`) && seen.add(`${x.kind}|${x.en}`));
301	}
302	
303	function terms(o) {
304	  const dir = dirOf(o.module);
305	  const snap = JSON.parse(readFileSync(join(dir, 'snapshot.json'), 'utf8'));
306	  const known = loadTerms(dir);
307	  const todo = termSources(snap).filter((x) => !known[x.kind]?.[x.en]);
308	  const tdir = join(dir, 'terms', '_in');
309	  ensureDirSync(tdir);
310	  const first = Math.max(0, ...readdirSync(tdir).map((f) => Number(/^t(\d{3})\.json$/.exec(f)?.[1] || 0)));
311	  const size = 150;
312	  const manifest = [];
313	  for (let i = 0; i < todo.length; i += size) {
314	    const name = `t${String(first + i / size + 1).padStart(3, '0')}`;
315	    const items = todo.slice(i, i + size).map((x, j) => ({ id: `${name}-${String(j + 1).padStart(3, '0')}`, ...x }));
316	    atomicWriteFileSync(join(tdir, `${name}.json`), JSON.stringify({ module: o.module, lang: snap.meta.lang || 'ko', items }, null, 1));
317	    manifest.push({ batch: name, file: join(tdir, `${name}.json`), terms: items.length });
318	  }
319	  process.stdout.write(JSON.stringify({ terms: todo.length, batches: manifest }, null, 1) + '\n');
320	}
321	
322	export function parseTerms(text) {
323	  const out = {};
324	  for (const line of String(text).replace(/\r\n/g, '\n').split('\n')) {
325	    const m = /^\s*(t\d{3}-\d{3})\s*=\s*(.+?)\s*$/.exec(line);
326	    if (m) out[m[1]] = m[2].split('|')[0].trim();
327	  }
328	  return out;
329	}
330	
331	/** { folder: {en: ko}, activity: {…}, label: {…} } — reviewer corrections win over drafts. */
332	export function loadTerms(dir) {
333	  const tdir = join(dir, 'terms');
334	  const out = { folder: {}, activity: {}, label: {} };
335	  if (!existsSync(join(tdir, '_in'))) return out;
336	  for (const f of readdirSync(join(tdir, '_in')).filter((x) => /^t\d{3}\.json$/.test(x))) {
337	    const b = f.slice(0, 4);
338	    const read = (k) => (existsSync(join(tdir, `${b}.${k}.json`)) ? JSON.parse(readFileSync(join(tdir, `${b}.${k}.json`), 'utf8')).items : {});
339	    const draft = read('draft'), review = read('review');
340	    for (const it of JSON.parse(readFileSync(join(tdir, '_in', f), 'utf8')).items) {
341	      const ko = review[it.id] || draft[it.id];
342	      if (ko) out[it.kind][it.en] = ko; // also terms kept in English, so they are not asked again
343	    }
344	  }
345	  return out;
346	}
347	
348	// ── knowledge base: the system-independent part of reviewed notes, per module,
349	// language and IMG activity, under ~/.sc4sap/kb/config/ — reused by every later
350	// run and every other system, so only the system part is written again.
351	const GENERAL = ['purpose', 'sapdoc', 'mix', 'compare', 'checklist', 'criteria'];
352	const kbDir = (module, lang) => join(sc4sapHome(), 'kb', 'config', module, lang);
353	const kbFile = (module, lang, id) => join(kbDir(module, lang), `${id.replace(/[^A-Za-z0-9_-]/g, '_')}.json`);
354	export function kbRead(module, lang, id) {
355	  const f = kbFile(module, lang, id);
356	  return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : null;
357	}
358	
359	/** General part of one reviewed note (case verdicts are system-specific and left out). */
360	export function generalPart(note) {
361	  const out = Object.fromEntries(GENERAL.map((k) => [k, note[k]]));
362	  out.cases = note.cases ? { title: note.cases.title, list: note.cases.list.map(({ thisSystem, svg, ...c }) => c) } : null;
363	  out.sources = (note.sources || []).filter((s) => isOfficialSource(s.url));
364	  return out;
365	}
366	
367	/** Note + knowledge base: general fields filled from the KB, verdicts applied to its cases. */
368	export function withKb(note, entry) {
369	  if (!entry) return note;
370	  const out = { ...note };
371	  for (const k of GENERAL) if (!out[k] || (Array.isArray(out[k]) && !out[k].length) || (typeof out[k] === 'object' && !Array.isArray(out[k]) && !Object.keys(out[k]).length)) out[k] = entry[k];
372	  if (!out.sources?.length) out.sources = (entry.sources || []).map((s) => ({ ...s, fromKb: true }));
373	  if (!out.cases && entry.cases) {
374	    out.cases = { title: entry.cases.title, list: entry.cases.list.map((c, n) => ({ ...c, thisSystem: (note.verdicts || []).find((v) => v.n === n + 1)?.value || '' })) };
375	  }
376	  return out;
377	}
378	
379	function kbPromote(o) {
380	  const dir = dirOf(o.module);
381	  const lang = JSON.parse(readFileSync(join(dir, 'snapshot.json'), 'utf8')).meta.lang || 'ko';
382	  ensureDirSync(kbDir(o.module, lang));
383	  let saved = 0, kept = 0;
384	  for (const [id, n] of Object.entries(loadNotes(dir))) {
385	    if (!['ok', 'revised'].includes(n.review) || !n.cases || n.fromKb) continue;
386	    if (!o.redo && kbRead(o.module, lang, id)) { kept++; continue; }
387	    atomicWriteFileSync(kbFile(o.module, lang, id), JSON.stringify({ activity: id, module: o.module, lang, savedAt: new Date().toISOString(), ...generalPart(n) }, null, 1));
388	    saved++;
389	  }
390	  process.stdout.write(JSON.stringify({ kb: kbDir(o.module, lang), saved, kept }) + '\n');
391	}
392	
393	/** Merge drafts, reviews and revisions: { id: { ...note, review: 'ok'|'revised'|'open'|'none', issues } }. */
394	export function loadNotes(dir, { module = '', lang = 'ko' } = {}) {
395	  const ndir = join(dir, 'notes');
396	  if (!existsSync(ndir)) return {};
397	  const read = (f) => (existsSync(join(ndir, f)) ? JSON.parse(readFileSync(join(ndir, f), 'utf8')).items : {});
398	  const out = {};
399	  for (const b of readdirSync(ndir).filter((f) => /^b\d{3}\.draft\.json$/.test(f)).map((f) => f.slice(0, 4))) {
400	    const draft = read(`${b}.draft.json`), review = read(`${b}.review.json`), revised = read(`${b}.revised.json`);
401	    for (const [id, note] of Object.entries(draft)) {
402	      const r = review[id];
403	      const fixed = revised[id];
404	      const n = fixed || note;
405	      const m = module ? withKb(n, kbRead(module, lang, id)) : n;
406	      out[id] = { ...m, sources: (m.sources || []).filter((s) => isOfficialSource(s.url)), review: fixed ? 'revised' : r ? (r.verdict === 'ok' ? 'ok' : 'open') : 'none', issues: fixed ? [] : r?.issues || [] };
407	    }
408	  }
409	  return out;
410	}
411	
412	function status(o) {
413	  const ndir = join(dirOf(o.module), 'notes');
414	  const ins = existsSync(join(ndir, '_in')) ? readdirSync(join(ndir, '_in')).filter((f) => f.endsWith('.json')).map((f) => f.slice(0, 4)) : [];
415	  const has = (b, k) => existsSync(join(ndir, `${b}.${k}.json`));
416	  process.stdout.write(JSON.stringify(ins.map((b) => ({ batch: b, draft: has(b, 'draft'), review: has(b, 'review'), revised: has(b, 'revised') })), null, 1) + '\n');
417	}
418	
419	if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
420	  try {
421	    const o = opts(process.argv.slice(2));
422	    const run = { batches, scopes: batches, terms, kb: kbPromote, sources: seedSources, save, status }[o.cmd];
423	    if (!run) throw new Error('command: scopes | batches | terms | kb | sources | save | status');
424	    run(o);
425	  } catch (e) {
426	    process.stderr.write(`[notes] ${e.message}\n`);
427	    process.exit(1);
428	  }
429	}
