// Per-run metrics of subagents whose description matches a regex.
// Usage: node measure-run.mjs <projectsDir> <descRegex> [excludeRegex]
import fs from 'node:fs';
import path from 'node:path';

const [root, inc, exc] = process.argv.slice(2);
const re = new RegExp(inc, 'i');
const ex = exc ? new RegExp(exc, 'i') : null;
const PRICE = { opus: [5, 25], sonnet: [3, 15], haiku: [1, 5] };
const tier = (m = '') => (/haiku/i.test(m) ? 'haiku' : /sonnet/i.test(m) ? 'sonnet' : 'opus');

function walk(d, acc) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p, acc);
    else if (e.name.endsWith('.meta.json') && d.endsWith('subagents')) acc.push(p);
  }
  return acc;
}

const runs = [];
for (const mp of walk(root, [])) {
  let m; try { m = JSON.parse(fs.readFileSync(mp, 'utf8')); } catch { continue; }
  const d = m.description || '';
  if (!re.test(d) || (ex && ex.test(d)) || !/consultant/.test(m.agentType || '')) continue;
  const seen = new Map(); const toolIds = new Set(); const tools = {}; let outChars = 0, model = m.model, first = '';
  for (const l of fs.readFileSync(mp.replace(/\.meta\.json$/, '.jsonl'), 'utf8').split('\n')) {
    if (!l) continue; let o; try { o = JSON.parse(l); } catch { continue; }
    if (!first && o.timestamp) first = o.timestamp;
    if (o.type !== 'assistant' || !o.message) continue;
    const g = o.message; model = g.model || model;
    if (g.id && g.usage && !seen.has(g.id)) seen.set(g.id, g.usage);
    for (const c of g.content || []) {
      if (c.type === 'tool_use') {
        if (toolIds.has(c.id)) continue; toolIds.add(c.id);
        const s = String(c.input?.command || '');
        const k = c.name !== 'Bash' ? c.name : /notes\.mjs rows/.test(s) ? 'Bash:rows' : /snapshot\.json/.test(s) ? 'Bash:snapshot' : /notes\.mjs save/.test(s) ? 'Bash:save' : /cat >>?/.test(s) ? 'Bash:write' : /curl|wget/.test(s) ? 'Bash:curl' : 'Bash:other';
        tools[k] = (tools[k] || 0) + 1; outChars += JSON.stringify(c.input || {}).length;
      } else outChars += (c.text || c.thinking || '').length;
    }
  }
  const u = [...seen.values()];
  const [pi, po] = PRICE[tier(model)];
  const usd = u.reduce((s, x) => s + ((x.input_tokens || 0) + 1.25 * (x.cache_creation_input_tokens || 0) + 0.1 * (x.cache_read_input_tokens || 0)) * pi / 1e6, 0) + (outChars / 3) * po / 1e6;
  const t0 = first ? new Date(first) : null;
  runs.push({ desc: d, at: first.slice(0, 16), calls: u.length, usd, tools, model: tier(model), ctxEnd: u.length ? (u.at(-1).cache_read_input_tokens || 0) + (u.at(-1).cache_creation_input_tokens || 0) : 0 });
}
const avg = (k) => runs.reduce((s, r) => s + r[k], 0) / Math.max(runs.length, 1);
const toolAvg = {};
for (const r of runs) for (const [k, v] of Object.entries(r.tools)) toolAvg[k] = (toolAvg[k] || 0) + v / runs.length;
console.log(JSON.stringify({ runs: runs.length, callsAvg: +avg('calls').toFixed(1), usdAvg: +avg('usd').toFixed(2), ctxEndAvgK: Math.round(avg('ctxEnd') / 1000), tools: Object.fromEntries(Object.entries(toolAvg).map(([k, v]) => [k, +v.toFixed(1)]).sort((a, b) => b[1] - a[1])) }));
if (runs.length <= 3) for (const r of runs) console.log(JSON.stringify({ ...r, usd: +r.usd.toFixed(2) }));

