        methods: src.methods.filter((m) => !m.empty).map((m) => ({ name: m.name, lines: m.lines, refs: m.refs, truncated: m.truncated, source: m.source })),
        emptyMethods: src.methods.filter((m) => m.empty).map((m) => m.name),
        includes: includesOf(src),
